108:/**
109: * What the posting reaches and what the candidate may work under, for the
110: * authorization question that names no country of its own.
111: */
112:export interface JobReach {
113:  /** The posting's location line, as the job row holds it. */
114:  location: string | null | undefined;
115:  /** The posting speaking about its own reach (`worldwide`, `us_only`, …). */
116:  remoteScope?: string | null;
117:  /** Countries the candidate may work in, from `profile.eligibility`. */
118:  workCountries: string[];
119:}
120:
121:/**
122: * May the candidate work where this posting's work happens?
123: *
124: * NOT `reachAllows`, and the difference is the whole point. That function
125: * answers "can this candidate take this job", where a worldwide-remote posting
126: * is a yes whatever its location line says. This one answers "is the candidate
127: * authorized in the country the posting names", and there a location line
128: * reading "San Francisco, California, USA" decides even when the row also says
129: * `worldwide` — the scope is the company describing how it hires, the line is
130: * where the work sits, and answering yes to the US on the strength of the
131: * scope is precisely the fabrication this branch exists to stop. Measured
132: * against 40 real postings on 2026-08-19: using `reachAllows` claimed US
133: * authorization on Atlassian (San Francisco) and Overvak (New York), and
134: * denied it on three Brazilian postings for a Brazilian candidate.
135: *
136: * So: a named country decides; only a posting that names none falls back to
137: * "hires anywhere", which means the candidate works from home and is
138: * authorized there.
139: */
140:function whereTheWorkIs(job: JobReach): "yes" | "no" | "unknown" {
141:  const places = namedPlaces(job.location, job.remoteScope);
142:  if (!job.workCountries.length) return "yes";
143:  if (places.countries.length) {
144:    return places.countries.some((c) => job.workCountries.includes(c))
145:      ? "yes"
146:      : "no";
147:  }
148:  if (places.open) return "yes";
149:  return reachAllows(places, job.workCountries) === "yes" ? "yes" : "unknown";
150:}
