359:/**
360: * Can a candidate who may work in `workCountries` take a posting that names
361: * `places`?
362: *
363: * Only three answers are possible, and the third is the important one: a
364: * posting that names nowhere at all is `"unknown"`, never `"no"`. Naming
365: * nothing is the normal state of half the boards we read.
366: */
367:export function reachAllows(
368:  places: NamedPlaces,
369:  workCountries: string[],
370:): "yes" | "no" | "unknown" {
371:  if (places.open) return "yes";
372:  if (!workCountries.length) return "unknown";
373:  if (!places.countries.length && !places.regions.length) return "unknown";
374:  for (const c of places.countries) {
375:    if (workCountries.includes(c)) return "yes";
376:  }
377:  for (const r of places.regions) {
378:    if (workCountries.some((c) => regionCovers(r, c))) return "yes";
379:  }
380:  return "no";
381:}
